/* Inlined images (this repo is text-only). Sets the logo and sample car before the widget boots. */
(function(){var L="data:image/png;base64,",C="data:image/jpeg;base64,";
var w=document.querySelector('[data-wheel-visualizer]');if(w){w.setAttribute('data-logo',L);w.setAttribute('data-sample-car',C);}
var h=document.getElementById('cali-logo');if(h)h.src=L;})();
